insert into public.catalog_packages (key, grp, sort, highlight, price_cents, price_unit, term_months, free_months, setup_cents, texts, bullets, meta) values ('addon_shop', 'addon', 10, false, null, 'month', null, 0, null, '{"de": {"name": "Online-Shop", "tagline": "Gäste kaufen ihr Foto auch nach dem Besuch: Download, Abzug, Tasse, T-Shirt, Wandbild.", "price_note": "99 € / Monat + 749 € Einrichtung, oder 15 % Umsatzanteil ohne Fixkosten"}, "en": {"name": "Online shop", "tagline": "Guests buy their photo after the visit too: download, print, mug, T-shirt, wall art.", "price_note": "€99 / month + €749 setup, or 15% revenue share with no fixed costs"}, "es": {"name": "Tienda online", "tagline": "Los invitados compran su foto también después de la visita: descarga, copia, taza, camiseta, cuadro.", "price_note": "99 € / mes + 749 € de alta, o 15 % de los ingresos sin costes fijos"}, "fr": {"name": "Boutique en ligne", "tagline": "Les invités achètent leur photo même après la visite : téléchargement, tirage, tasse, t-shirt, tableau.", "price_note": "99 € / mois + 749 € d’installation, ou 15 % du chiffre d’affaires sans frais fixes"}, "it": {"name": "Negozio online", "tagline": "Gli ospiti acquistano la foto anche dopo la visita: download, stampa, tazza, t-shirt, quadro.", "price_note": "99 € / mese + 749 € di attivazione, oppure 15 % dei ricavi senza costi fissi"}, "nl": {"name": "Webshop", "tagline": "Gasten kopen hun foto ook na het bezoek: download, afdruk, mok, T-shirt, wanddecoratie.", "price_note": "€ 99 / maand + € 749 inrichting, of 15% omzetaandeel zonder vaste kosten"}, "lv": {"name": "Tiešsaistes veikals", "tagline": "Viesi pērk fotogrāfiju arī pēc apmeklējuma: lejupielāde, izdruka, krūze, T-krekls, sienas attēls.", "price_note": "99 € / mēnesī + 749 € ierīkošana, vai 15 % no ieņēmumiem bez fiksētām izmaksām"}}'::jsonb, '[]'::jsonb, '{}'::jsonb) on conflict (key) do nothing;
